int type = static_cast<int>(pk_read(row, base + PK_TYPE_OFF, PK_TYPE_BITS));
if (type < TYPE1 || type > TYPE5) return FAILAT();
int rec = scamp_type_cells(type);
if (rec == 2 && (w.cell & 1u)) return FAILAT();             /* even alignment */
int slot = w.bulk ? 2 : rec;
if (w.cell + static_cast<uint32_t>(slot) > C) return FAILAT();

