for (int k = 0; k < slot; ++k) {
    if (cover[s][w.cell + k] != -1) return FAILAT();        /* overlap / two parents */
    cover[s][w.cell + k] = idx;
}
if (slot == 2 && rec == 1) {                                /* bulk zero padding */
    if (!pk_zero(row, 128, 128)) return FAILAT();
}

nodes.emplace_back();
ValNode& n = nodes[idx];
n.stage = s;
n.cell = w.cell;
n.slot = static_cast<uint8_t>(slot);
n.rec = static_cast<uint8_t>(rec);
n.type = static_cast<uint8_t>(type);
n.origin = static_cast<uint8_t>(w.origin);
n.depth = static_cast<uint8_t>(w.depth);
n.region = w.region;
n.parent = w.parent;
if (w.ref >= 0) children[w.ref].node = idx;

n.bmp = static_cast<uint32_t>(pk_read(row, base + PK_BMP_OFF, PK_BMP_BITS));

/* ---- NI header ---- */
if (type <= TYPE3) {
    uint32_t bid = static_cast<uint32_t>(pk_read(row, base + PK_BID_OFF, PK_BID_BITS));
    uint32_t nib = static_cast<uint32_t>(pk_read(row, base + PK_NIB_OFF, PK_NIB_BITS));
    if (bid >= d->bitmaps.size()) return FAILAT();
    n.bitmap_id = bid;
    n.ni_base = nib;
    n.pattern = d->bitmaps[bid];
    if (n.pattern & 1ULL) return FAILAT();                  /* bit0 unused */
    uint32_t pc = scamp_popcount64(n.pattern);
    if (static_cast<uint64_t>(nib) + pc > d->nexthops.size()) return FAILAT();
    if (pc == 0 && nib != 0) return FAILAT();               /* empty arrays: base0 */
