    if (type == TYPE2 && !pk_zero(row, base + PK_T2_RSVD_OFF, 1)) return FAILAT();
    if (type == TYPE3 && !pk_zero(row, base + PK_T3_RSVD_OFF, PK_T3_RSVD_BITS)) return FAILAT();
