    cr.stage = cst;
    cr.cell = ccell;
    cr.node = -1;
    int32_t ref = static_cast<int32_t>(children.size());
    children.push_back(cr);
    ++n.ch_count;
    ++nchild;
    Work cw;
    cw.stage = cst;
    cw.cell = ccell;
    cw.bulk = false;
    cw.origin = w.origin;
    cw.depth = w.depth + 6;
    cw.region = w.region | (static_cast<u128_t>(key) << (128 - (w.depth + 6)));
    cw.parent = idx;
    cw.ref = ref;
    q.push_back(cw);
}

/* ---- bulk children ---- */
if (type == TYPE3) {
    uint64_t bm = pk_read(row, base + PK_BULK_BM_OFF, PK_BULK_BM_BITS);
