        ++nchild;
        Work cw;
        cw.stage = bstg;
        cw.cell = cr.cell;
        cw.bulk = true;
        cw.origin = w.origin;
        cw.depth = w.depth + 6;
        cw.region = w.region | (static_cast<u128_t>(k) << (128 - (w.depth + 6)));
        cw.parent = idx;
        cw.ref = ref;
        q.push_back(cw);
        ++i;
    }
}

if (type == TYPE2 && (nchild < 3 || nchild > 6)) return FAILAT();
