        if (L < w.depth) return FAILAT();                               /* reaches the node */
        if (L > max) return FAILAT();
        if (scamp_mask(p.addr, w.depth) != w.region) return FAILAT();   /* inside region */
        n.inl[i] = p;
        fib.push_back(p);
        if (fib.size() > SCAMP_PREFIX_LIMIT) return FAILAT();
    }
